class Solution:
    def findMaxLength(self, nums: List[int]) -> int:
        s = 0
        mx = 0
        dic = {}
        for i, v in enumerate(nums):
            s += 1 if v == 1 else -1
            if s == 0:
                mx = i + 1
            elif s in dic:
                mx = max(mx, i - dic[s])
            else:
                dic[s] = i
        return mx

class NumArray:

    def __init__(self, nums: List[int]):
        self.nums = nums
        self.numsum = []
        l = len(nums)
        for i in range(l):
            if len(self.numsum) == 0:
                self.numsum.append(self.nums[i])
            else:
                self.numsum.append(self.numsum[i-1]+self.nums[i])
    def sumRange(self, left: int, right: int) -> int:
        if left == 0:
            return self.numsum[right]
        return self.numsum[right] - self.numsum[left-1]



